const titles={dashboard:['Founder Dashboard','Your complete operating overview'],businesses:['Businesses','Manage every business inside this workspace.'],employees:['Employees','Manage people, roles and team access.'],departments:['Departments','Organise teams and operational functions.'],roles:['Roles & Permissions','Define access and responsibility levels.'],'task-library':['Master Task Library','Create reusable operational tasks and SOPs.'],tasks:['Tasks','Plan, assign and track all work.'],workflow:['Workflow','Move work from To Do to Done.'],calendar:['Calendar','View deadlines, meetings and leave.'],attendance:['Attendance & Leave','Track live attendance, breaks, leave and working hours.'],reports:['Attendance & Workload','Attendance, capacity and smart task assignment.'],settings:['Settings','Configure your founder workspace.'],'ai-copilot':['Founder Copilot','AI-powered planning, prioritisation and operational guidance.']};
